// BenchmarkAdversarial_MixedVectors measures the cost of the reference monitor under a
// rotating mix of malicious and legitimate requests.
func BenchmarkAdversarial_MixedVectors(b *testing.B) {
	svc := NewMockGPUService(capability.ModeSimulated).(*mockGPUService)
	defer svc.Close()
	ctx := context.Background()
	handle, _ := svc.Alloc(ctx, 1024*1024)
	grant := &Grant{GPU: &GPURule{AllowedDevices: []int{0}}}

	b.ResetTimer()
	b.ReportAllocs()
	for i := 0; i < b.N; i++ {
		switch i % 5 {
		case 0:
			_, _ = GetZeroView(ctx, svc, grant, handle, 2_000_000, 1024) // OOB offset
		case 1:
			_, _ = GetZeroView(ctx, svc, grant, handle, 900*1024, 200*1024) // clamp
		case 2:
			_, _ = GetZeroView(ctx, svc, grant, 999_999_999_999, 0, 1024) // forged
		case 3:
			_, _ = GetZeroView(ctx, svc, grant, handle, 0, 1024) // legitimate
		case 4:
			_, _ = GetZeroView(ctx, svc, nil, handle, 0, 1024) // nil grant
		}
	}
}
